2. 新增 resolveSkillPaths 函数。放在 getPiInvocation 之后、runSingleAgent 之前，或者在 runSingleAgent 之前。需要 fs, path, os（都已 import）。

```ts
/**
 * Resolve an agent's skill whitelist to concrete file paths.
 *
 * Strict whitelist: the caller always passes `--no-skills` to the child, so only
 * skills listed here are visible. Entries may be skill names (resolved against
 * pi's default `.pi` skill discovery) or filesystem paths.
 *
 * Returns `paths` to feed to `--skill`, plus `missing` (unresolved entries) and
 * `available` (all discovered skill names, for error messages).
 */
function resolveSkillPaths(
	agentSkills: string[],
	cwd: string,
): { paths: string[]; missing: string[]; available: string[] } {
	const result = loadSkills({
		cwd,
		agentDir: getAgentDir(),
		skillPaths: [],
		includeDefaults: true,
	});

	const byName = new Map<string, string>();
	for (const skill of result.skills) byName.set(skill.name, skill.filePath);
	const available = Array.from(byName.keys()).sort();

	const paths: string[] = [];
	const missing: string[] = [];
	const seen = new Set<string>();

	for (const entry of agentSkills) {
		const trimmed = entry.trim();
		if (!trimmed) continue;

		const looksLikePath =
			trimmed.includes(path.sep) || trimmed.startsWith(".") || trimmed.startsWith("~");
		let resolved: string | undefined;
		if (looksLikePath) {
			const expanded = trimmed.startsWith("~")
				? path.join(os.homedir(), trimmed.slice(1))
				: trimmed;
			const abs = path.isAbsolute(expanded) ? expanded : path.resolve(cwd, expanded);
			if (fs.existsSync(abs)) resolved = abs;
		} else {
			resolved = byName.get(trimmed);
		}

		if (!resolved) {
			missing.push(trimmed);
		} else if (!seen.has(resolved)) {
			seen.add(resolved);
			paths.push(resolved);
		}
	}

	return { paths, missing, available };
}
```

注意 Windows path.sep —— 项目跑在 Linux，但 path.sep 在 Windows 是 `\`。looksLikePath 判断 `trimmed.includes(path.sep)` 在 Windows 下对 `foo/bar` 可能漏判，但 startsWith(".") / "~" 仍能覆盖相对/家目录。绝对路径在 Windows 是 `C:\` 含 `\` = path.sep。够用。不纠结跨平台边缘。

